  },
  {
    id: "wegen-aufgrund-genitive-nominal",
    directive: "Write a sentence using a nominal causal phrase with 'wegen' or 'aufgrund' followed by a genitive-marked nominalization, e.g. 'Wegen des starken Regens fällt das Konzert aus.'",
    share: 1,
  },
],

