    share: 3,
  },
  {
    id: "main-clause-connector-inversion",
    directive: "Write an exercise targeting a main-clause consecutive connector (folglich, infolgedessen, or demzufolge) placed in first position, forcing V2 inversion (connector – verb – subject). Example: 'Der Zug hatte Verspätung; infolgedessen verpassten wir den Anschluss.' The connector must occupy position 1 and the finite verb must immediately follow it.",
    share: 3,
  },
  {
    id: "zu-als-dass-konjunktiv-ii",
    directive: "Write an exercise targeting the negative-result construction 'zu + adjective/adverb … als dass' with Konjunktiv II in the subordinate clause. Example: 'Das Problem ist zu komplex, als dass man es schnell lösen könnte.' The main clause must contain 'zu + adjective', and the 'als dass'-clause must use Konjunktiv II.",
    share: 3,
  },
],

